const items = $input.all();
const inputData = $input.first().json;
const nombreAsesor = inputData.nombre_asesor?.trim() || null;

function normalizar(str) {
  return str
    .toUpperCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

const NOMBRES_BLOQUEADOS = ["SERVICIO MOVIL"];

const todosLosAsesores = items
  .map(i => i.json)
  .filter(a => {
    if (a.advisorId === 146715) return false;
    if (NOMBRES_BLOQUEADOS.includes(normalizar(a.advisorName || ""))) return false;
    return true;
  });

if (nombreAsesor) {
  const palabras = normalizar(nombreAsesor).split(/\s+/).filter(p => p.length > 0);
  const match = todosLosAsesores.find(a => {
    const nombre = normalizar(a.advisorName || '');
    return palabras.every(p => nombre.includes(p));
  });
  if (match) {
    return {
      json: {
        advisorId: match.advisorId,
        advisorName: match.advisorName,
        schedules: match.schedules
      }
    };
  }
}

const randomIndex = Math.floor(Math.random() * todosLosAsesores.length);
const selected = todosLosAsesores[randomIndex];
return {
  json: {
    advisorId: selected.advisorId,
    advisorName: selected.advisorName,
    schedules: selected.schedules
  }
};

const items = $input.all();
if (!items.length) throw new Error('No hay datos de entrada');

let raw = items[0].json;
let cliente;
if (Array.isArray(raw)) {
  if (!raw.length) throw new Error('El array de entrada está vacío');
  cliente = raw[0];
} else {
  cliente = raw;
}
if (!cliente || typeof cliente !== 'object') throw new Error('Formato de entrada inválido');

function getKmFrequency(groupR, modelYear) {
  const year = parseInt(modelYear) || 0;

  switch (groupR) {
    case 1:  return 15000; // KA
    case 2:
    case 3:  return 15000; // FIESTA
    case 4:  return 15000; // ECOSPORT
    case 6:  return 15000; // FOCUS
    case 8:  return 15000; // S-MAX
    case 9:                // RANGER generaciones viejas
      return year >= 2024 ? 16000 : 10000;
    case 11: return 15000; // COURIER
    case 12: return 15000; // KUGA
    case 13: return 15000; // OTROS
    case 14:               // TRANSIT
      return year >= 2021 ? 16000 : 15000;
    case 15: return 15000; // MONDEO
    case 16: return 15000; // MUSTANG
    case 17:
    case 25: return 15000; // F-150 / F-250
    case 18: return 15000; // F-150 RAPTOR
    case 19: return 10000; // TERRITORY
    case 20: return 16000; // BRONCO SPORT
    case 22: return 15000; // MAVERICK
    case 23: return 15000; // CARGO
    case 24: return 16000; // RANGER (P703)
    case 26: return 16000; // MACH-E
    case 27: return 16000; // RANGER RAPTOR (P703)
    case 28: return 16000; // BRONCO
    case 30: return 16000; // EVEREST
    default: return 15000; // fallback general
  }
}

const resultado = {
  customerK:       cliente.customerK ?? null,
  model:           cliente.model || null,
  model_id:        cliente.groupR || null,
  plate:           cliente.plate || null,
  chassi:          cliente.chassi || null,
  nationalId:      cliente.nationalId || null,
  firstname:       cliente.firstname || null,
  lastname:        cliente.lastname || null,
  email:           cliente.email || null,
  id_conversation: String($("When Executed by Another Workflow").first().json.id_conversation),
  company:         1,
  km_frequency:    getKmFrequency(cliente.groupR, cliente.modelYear),
};

return [{ json: resultado }];

// Obtenemos todos los items del input
const items = $input.all();

if (!items.length) {
  throw new Error('No hay datos de entrada');
}

let root = items[0].json;

if (Array.isArray(root)) {
  if (!root.length) throw new Error('El array raíz está vacío');
  root = root[0];
}

if (!root || typeof root !== 'object') {
  throw new Error('Formato de entrada inválido');
}

const services = Array.isArray(root.response) ? root.response : [];
if (!services.length) {
  throw new Error('No se encontraron servicios en root.response');
}

// 🔥 Normaliza texto (sin tildes, minúscula)
function normalizeText(text) {
  return (text ?? "")
    .toString()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();
}

const output = [];

for (const svc of services) {
  const serviceNameNorm = normalizeText(svc.serviceName);

  // ❌ Excluir Servicio Móvil (incluye "(Online)")
  if (serviceNameNorm.includes("servicio movil")) {
    continue;
  }

  // ❌ Excluir Lavado Complementario (incluye typo)
  if (
    serviceNameNorm.includes("lavado complementario") ||
    serviceNameNorm.includes("lavado complemetario")
  ) {
    continue;
  }

  // ❌ Excluir Lavado de Cortesía
  if (
    serviceNameNorm.includes("lavado de cortesia") ||
    serviceNameNorm.includes("lavado cortesia")
  ) {
    continue;
  }

  const servicesByModelGroup = Array.isArray(svc.servicesByModelGroup)
    ? svc.servicesByModelGroup
    : [];

  let promo = null;
  for (const mg of servicesByModelGroup) {
    if (mg.promotionalActive) {
      promo = mg;
      break;
    }
  }

  const price = promo && typeof promo.promotionalPrice === 'number'
    ? promo.promotionalPrice
    : svc.servicePrice ?? null;

  const simplified = {
    serviceId: svc.serviceId,
    name: svc.serviceName,
    description: svc.name ?? null,
    price,
    normalPrice: svc.servicePrice ?? null,
    isPromo: !!(promo && promo.promotionalActive),
  };

  output.push({ json: simplified });
}

return output;

// Obtener input
const items = $input.all();

if (!items.length) {
  throw new Error('No hay datos de entrada');
}

// El input que mostraste es:
// [ { httpCode, message, response: [ { ...mantenimiento }, ... ] } ]
let root = items[0].json;

if (Array.isArray(root)) {
  if (!root.length) throw new Error('El array raíz está vacío');
  root = root[0];
}

if (!root || typeof root !== 'object') {
  throw new Error('Formato de entrada inválido');
}

const list = Array.isArray(root.response) ? root.response : [];
if (!list.length) {
  throw new Error('No se encontraron mantenimientos en root.response');
}

// Normalizamos fecha a "solo día"
function toDateOnly(value) {
  if (!value) return null;
  const d = new Date(value);
  if (isNaN(d.getTime())) return null;
  d.setHours(0, 0, 0, 0);
  return d;
}

const now = new Date();
now.setHours(0, 0, 0, 0);

const output = [];

for (const item of list) {
  const start = toDateOnly(item.modelStartDate);
  const end = toDateOnly(item.modelEndDate);

  if (!start || !end) {
    continue; // si no tiene fechas válidas, lo salteamos
  }

  // vigente si: start <= now <= end
  if (start <= now && now <= end) {
    output.push({
      json: {
        maintenanceCode: item.maintenanceCode,
        months: item.mounths ?? null, // el campo viene como "mounths"
        price: item.price ?? null,
      },
    });
  }
}

return output;

// Obtenemos los items de entrada
const items = $input.all();

if (!items.length) {
  throw new Error('No hay datos de entrada');
}

// El input viene como:
// [ { httpCode, message, response: [ { ...servicio }, ... ] } ]
let root = items[0].json;

if (Array.isArray(root)) {
  if (!root.length) {
    throw new Error('El array raíz está vacío');
  }
  root = root[0];
}

if (!root || typeof root !== 'object') {
  throw new Error('Formato de entrada inválido');
}

const list = Array.isArray(root.response) ? root.response : [];
if (!list.length) {
  throw new Error('No se encontraron servicios en root.response');
}

// Helper para normalizar fechas a "solo día"
function toDateOnly(value) {
  if (!value) return null;
  const d = new Date(value);
  if (isNaN(d.getTime())) return null;
  d.setHours(0, 0, 0, 0);
  return d;
}

// Helper para parsear montos (string o number)
function toNumber(value) {
  if (value === null || value === undefined) return 0;
  if (typeof value === 'number') return value;
  const s = String(value).replace(',', '.');
  const n = Number(s);
  return isNaN(n) ? 0 : n;
}

// Fecha actual (Argentina, pero solo día nos alcanza)
const now = new Date();
now.setHours(0, 0, 0, 0);

// Filtramos servicios vigentes hoy
const vigentes = list.filter(item => {
  const start = toDateOnly(item.modelStartDate);
  const end = toDateOnly(item.modelEndDate);
  if (!start || !end) return false;
  return start <= now && now <= end;
});

if (!vigentes.length) {
  throw new Error('No hay servicios vigentes para la fecha actual');
}

// Tomamos el primero vigente (en tu caso el de diciembre)
const svc = vigentes[0];

// Calculamos precio de ítems
const parts = Array.isArray(svc.revisionPartVOs) ? svc.revisionPartVOs : [];

let totalPartsPrice = 0;
const includedItems = parts.map(p => {
  const qty = toNumber(p.quantity);
  const price = toNumber(p.price);
  const subtotal = qty * price;
  totalPartsPrice += subtotal;

  return {
    description: p.longDescription || p.shortDescription || null,
    quantity: qty,
    unitPrice: price,
    subtotal,
  };
});

// Mano de obra
const labor = toNumber(svc.costLabor);

// Precio total = mano de obra + repuestos
// Si Ford no desglosa repuestos ni mano de obra, usa el precio total que informa
const totalPrice = (labor + totalPartsPrice) > 0 ? (labor + totalPartsPrice) : toNumber(svc.price);

// Agregar items adicionales fijos
includedItems.push(
  {
    description: "Control de 25 puntos de seguridad",
    quantity: 1,
    unitPrice: 0,
    subtotal: 0,
  },
  {
    description: "Lectura de códigos de falla con scanner FORD",
    quantity: 1,
    unitPrice: 0,
    subtotal: 0,
  }
);
// Armamos salida simple
const result = {
  serviceId: svc.serviceId,
  serviceCode: svc.service,             // ej: SM01
  serviceDescription: svc.serviceDescription,
  monthService: svc.monthService,

  totalPrice,

  includes: includedItems,
};

return [
  {
    json: result,
  },
];

// km: busca primero en el trigger, luego en la base de datos, o usa 15000 por defecto para pruebas
const triggerKm = $('When Executed by Another Workflow').first().json.km;
const dbData = $('Select rows from a table2').first().json;
const dbKm = dbData.km;

// Si viene string lo parsea a número, si no viene toma 0
const kmRaw = Number(triggerKm || dbKm || 0);

// km_frequency viene de la base de datos o toma 15000 por defecto
const kmFrequency = Number(dbData.km_frequency) || 15000;

// Si km viene en 0 o null, asume el primer service (kmFrequency)
const kmEfectivo = kmRaw > 0 ? kmRaw : kmFrequency;

// Redondear km al múltiplo de km_frequency más cercano (mínimo km_frequency)
const kmRedondeado = Math.max(kmFrequency, Math.round(kmEfectivo / kmFrequency) * kmFrequency);

// Cálculo del número de servicio y meses
const serviceNumber = Math.round(kmRedondeado / kmFrequency);
const months = Math.max(12, serviceNumber * 12);

const SERVICIOS = {
  1:  1403,   // 1ª Revisión de Mantenimiento
  2:  1404,   // 2ª
  3:  1405,   // 3ª
  4:  1406,   // 4ª 
  5:  1407,   // 5ª
  6:  1408,   // 6ª
  7:  1409,   // 7ª
  8:  1410,   // 8ª
  9:  1411,   // 9ª
  10: 1412,   // 10ª
  11: 1413,   // 11ª
  12: 1414,   // 12ª
  13: 1415,   // 13ª
  14: 1416,   // 14ª
  15: 1417,   // 15ª
  16: 1418,   // 16ª
  17: 1419    // 17ª 
};

const serviceId = SERVICIOS[serviceNumber] || (1402 + serviceNumber);

return [
  {
    json: {
      km_original: kmRaw,
      km_redondeado: kmRedondeado,
      km_frequency: kmFrequency,
      service_number: serviceNumber,
      service_id: serviceId,
      months,
    }
  }
];

const fechaActual = $('Loop Over Items1').item.json.date;

function toMinutes(hhmm) {
  if (!hhmm) return null;
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

function toHHMM(mins) {
  const h = String(Math.floor(mins / 60)).padStart(2, '0');
  const m = String(mins % 60).padStart(2, '0');
  return `${h}:${m}`;
}

const data = $input.first().json.result;
const specialists = data?.technicalSpecialists || [];
const schedules = data?.schedules || [];
const resultado = [];

for (const esp of specialists) {
  const specialtyIds = (esp.specialties || []).map(s => s.id);

  const firstShift = esp.workSchedule?.firstShift;
  const secondShift = esp.workSchedule?.secondShift;

  // Si está totalmente no disponible o no tiene turnos configurados
  if (esp.availability?.totallyUnavailable || (!firstShift && !secondShift)) {
    resultado.push({
      json: {
        fechaActual,
        advisorName: esp.advisorName,
        Huecos_Libres: [],
        specialtyIds
      }
    });
    continue;
  }

  // Obtenemos los bloqueos de indisponibilidad (soporta unavailableTimes y unavailablePeriods)
  const unavailableList = esp.availability?.unavailableTimes || esp.availability?.unavailablePeriods || [];

  const bloqueosIndisponibilidad = unavailableList
    .map(p => {
      const ini = toMinutes(p.startTime || p.start || p.entry);
      const fin = toMinutes(p.endTime || p.end || p.exit);
      return (ini !== null && fin !== null) ? [ini, fin] : null;
    })
    .filter(Boolean);

  // Obtenemos las citas ya agendadas
  const citasAgendadas = schedules
    .filter(s => s.productiveId === esp.advisorId || s.advisorId === esp.advisorId)
    .map(s => {
      const ini = toMinutes(s.startTime || s.start);
      const fin = toMinutes(s.endTime || s.end);
      return (ini !== null && fin !== null) ? [ini, fin] : null;
    })
    .filter(Boolean);

  // Unificamos y ordenamos todos los intervalos ocupados
  const ocupados = [...bloqueosIndisponibilidad, ...citasAgendadas].sort((a, b) => a[0] - b[0]);

  const turnosTrabajo = [];
  if (firstShift?.entry && firstShift?.exit) {
    turnosTrabajo.push([toMinutes(firstShift.entry), toMinutes(firstShift.exit)]);
  }
  if (secondShift?.entry && secondShift?.exit) {
    turnosTrabajo.push([toMinutes(secondShift.entry), toMinutes(secondShift.exit)]);
  }

  const huecos = [];
  for (const [inicioTurno, finTurno] of turnosTrabajo) {
    let cursor = inicioTurno;
    for (const [ini, fin] of ocupados) {
      if (fin <= cursor || ini >= finTurno) continue;
      if (ini > cursor) {
        huecos.push([cursor, Math.min(ini, finTurno)]);
      }
      cursor = Math.max(cursor, fin);
    }
    if (cursor < finTurno) {
      huecos.push([cursor, finTurno]);
    }
  }

  resultado.push({
    json: {
      fechaActual,
      advisorName: esp.advisorName,
      Huecos_Libres: huecos.map(([ini, fin]) => `${toHHMM(ini)} - ${toHHMM(fin)}`),
      specialtyIds
    }
  });
}

return resultado;

const fechaActual = $('Loop Over Items5').item.json.date;

function toMinutes(hhmm) {
  if (!hhmm) return null;
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

function toHHMM(mins) {
  const h = String(Math.floor(mins / 60)).padStart(2, '0');
  const m = String(mins % 60).padStart(2, '0');
  return `${h}:${m}`;
}

function generarSlots(entry, exit, interval) {
  const inicio = toMinutes(entry);
  const fin = toMinutes(exit);
  if (inicio === null || fin === null) return [];

  const slots = [];
  for (let t = inicio; t < fin; t += interval) {
    slots.push(toHHMM(t));
  }
  return slots;
}

const inputData = $input.first()?.json?.result?.advisorDealerSchedule;
const interval = inputData?.interval || 20;
const advisors = inputData?.advisors || [];

const resultado = advisors.map(a => {
  // 1. Días libres / Ausencias activas hoy
  const daysOffActivos = (a.daysOffs || []).filter(off => {
    return fechaActual >= off.startDay && fechaActual <= off.endDay;
  });

  // Si tiene día libre completo, 0 disponibles
  if (daysOffActivos.some(off => off.allDay)) {
    return {
      json: {
        fechaActual,
        advisorId: a.advisorId,
        advisorName: a.advisorName,
        Slots_Libres: [],
        Cantidad_Slots_Libres: 0
      }
    };
  }

  // Sets de exclusión
  const slotsDaysOff = new Set();
  daysOffActivos.forEach(off => {
    if (off.offStartHour && off.offEndHour) {
      generarSlots(off.offStartHour, off.offEndHour, interval).forEach(s => slotsDaysOff.add(s));
    }
  });

  const reservadosSinCita = new Set((a.nonScheduled || []).map(s => s.passerbyHour));

  const asignados = new Set(
    (a.dealerSchedule || [])
      .filter(s => s.dateSchedule === fechaActual)
      .map(s => s.hourSchedule)
  );

  // 2. Grilla base de jornada
  const gridCompleto = [
    ...generarSlots(a.amEntrance, a.amExit, interval),
    ...generarSlots(a.pmEntrance, a.pmExit, interval)
  ];

  // 3. Filtrar turnos disponibles
  const slotsLibres = gridCompleto.filter(h => 
    !reservadosSinCita.has(h) && 
    !asignados.has(h) && 
    !slotsDaysOff.has(h)
  );

  return {
    json: {
      fechaActual,
      advisorId: a.advisorId,
      advisorName: a.advisorName,
      Slots_Libres: slotsLibres,
      Cantidad_Slots_Libres: slotsLibres.length
    }
  };
});

if (resultado.length === 0) {
  return [{
    json: {
      fechaActual,
      vacio: true,
      Slots_Libres: [],
      Cantidad_Slots_Libres: 0
    }
  }];
}

return resultado;

const serviceTypes = $input.first().json.result.serviceTypes || [];

return serviceTypes
  .sort((a, b) => a.priority - b.priority)
  .map(s => ({
    json: {
      serviceTypeId: s.id,
      nombre: s.name,
      prioridad: s.priority,
      color: s.color
    }
  }));

const items = $input.all().map(i => i.json);

function toMinutes(hhmm) {
  if (!hhmm) return null;
  const [h, m] = hhmm.trim().split(':').map(Number);
  return h * 60 + m;
}

function toHHMM(minutes) {
  const h = Math.floor(minutes / 60).toString().padStart(2, '0');
  const m = (minutes % 60).toString().padStart(2, '0');
  return `${h}:${m}`;
}

const MAPA_SERVICIOS = {
  5: 'Mantenimiento',
  14: 'Taller Móvil',
  111: 'Mantenimiento - Kit IOLM',
  112: 'Reparación',
  113: 'Campañas De Servicio',
  114: 'Diagnóstico',
  115: 'Servicios Generales',
  116: 'Accesorios',
  117: 'Lavado',
  118: 'Colisión'
};

// Ids de specialty que cuentan como "hace Mantenimiento"
const IDS_MANTENIMIENTO = [5, 111];

const DURACION_TURNO_MINUTOS = 60;
const HORA_APERTURA = toMinutes('08:00');
const HORA_CIERRE   = toMinutes('17:00'); // último turno posible: 16:00-17:00

const resultado = [];

for (const item of items) {
  const fecha = item.fechaActual || item.fecha;
  const advisorName = item.advisorName || item.mecanicoNombre;
  const huecosEntrada = item.Huecos_Libres || item.huecosLibres || [];

  let servicios = item.servicios || [];
  if (servicios.length === 0 && Array.isArray(item.specialtyIds)) {
    servicios = item.specialtyIds.map(id => MAPA_SERVICIOS[id]).filter(Boolean);
  }

  // Solo mecánicos de Mantenimiento
  const haceMantenimiento = (item.specialtyIds && item.specialtyIds.some(id => IDS_MANTENIMIENTO.includes(id))) ||
    servicios.some(s => s.toLowerCase().includes('mantenimiento'));
  if (!haceMantenimiento) continue;

  // Parseamos los rangos libres una sola vez
  const rangosLibres = huecosEntrada
    .filter(r => r && r.includes('-'))
    .map(r => {
      const [ini, fin] = r.split('-').map(s => s.trim());
      return { ini: toMinutes(ini), fin: toMinutes(fin) };
    })
    .filter(r => r.ini !== null && r.fin !== null && r.fin > r.ini);

  const bloquesDisponibles = [];

  // Recorremos SIEMPRE la grilla fija en punto (08:00, 09:00, 10:00...)
  // en lugar de arrancar desde el minuto en que empieza cada hueco.
  for (
    let slotInicio = HORA_APERTURA;
    slotInicio + DURACION_TURNO_MINUTOS <= HORA_CIERRE;
    slotInicio += DURACION_TURNO_MINUTOS
  ) {
    const slotFin = slotInicio + DURACION_TURNO_MINUTOS;
    // El slot solo es válido si cae COMPLETO dentro de algún hueco libre
    const cabeEnAlgunHueco = rangosLibres.some(r => r.ini <= slotInicio && r.fin >= slotFin);
    if (cabeEnAlgunHueco) {
      bloquesDisponibles.push(`${toHHMM(slotInicio)} - ${toHHMM(slotFin)}`);
    }
  }

  if (bloquesDisponibles.length > 0) {
    resultado.push({
      json: {
        fecha,
        advisorName,
        servicios,
        huecosLibres: bloquesDisponibles
      }
    });
  }
}

return resultado;

const items = $input.all().map(i => i.json);

// ---------- Restricción de hora desde el trigger (ej: ">08:15", ">=09:00", "<12:00") ----------
function toMinutes(hhmm) {
  const match = String(hhmm ?? '').match(/(\d{1,2}):(\d{2})/);
  return match ? parseInt(match[1], 10) * 60 + parseInt(match[2], 10) : null;
}

let filtroHora = null;
try {
  const horaEspecifica = String($('When Executed by Another Workflow').first()?.json?.horaEspecifica ?? '').trim();
  const match = horaEspecifica.match(/^(>=|<=|>|<)\s*(\d{1,2}:\d{2})$/);
  if (match) filtroHora = { operador: match[1], minutos: toMinutes(match[2]) };
} catch (e) {}

function cumpleFiltroHora(slot) {
  if (!filtroHora) return true;
  const min = toMinutes(slot);
  if (min === null) return false;
  switch (filtroHora.operador) {
    case '>':  return min >  filtroHora.minutos;
    case '>=': return min >= filtroHora.minutos;
    case '<':  return min <  filtroHora.minutos;
    case '<=': return min <= filtroHora.minutos;
  }
  return true;
}

// Objeto para agrupar por fecha
const agrupadoPorFecha = {};

for (const item of items) {
  // Ignoramos registros vacíos o sin slots disponibles
  if (item.vacio || !item.Slots_Libres || item.Slots_Libres.length === 0) continue;

  // Aplicamos la restricción de hora (si viene)
  const slotsFiltrados = item.Slots_Libres.filter(cumpleFiltroHora);
  if (slotsFiltrados.length === 0) continue;

  const fecha = item.fechaActual;

  if (!agrupadoPorFecha[fecha]) {
    agrupadoPorFecha[fecha] = {
      fecha: fecha,
      asesores: [],
      todosLosSlotsDeLaFecha: new Set()
    };
  }

  agrupadoPorFecha[fecha].asesores.push({
    advisorId: item.advisorId,
    advisorName: item.advisorName,
    slotsDisponibles: slotsFiltrados,
    cantidadSlots: slotsFiltrados.length
  });

  // Consolidamos todos los horarios únicos disponibles en el día
  slotsFiltrados.forEach(slot => agrupadoPorFecha[fecha].todosLosSlotsDeLaFecha.add(slot));
}

// Formateamos la salida para n8n
return Object.values(agrupadoPorFecha).map(f => ({
  json: {
    fecha: f.fecha,
    totalAsesoresConDisponibilidad: f.asesores.length,
    slotsUnicosDelDia: Array.from(f.todosLosSlotsDeLaFecha).sort(),
    detalleAsesores: f.asesores
  }
}));

// Día de la semana y fecha en texto, calculados acá para que el agente no los tenga que deducir
const NOMBRES_DIAS_TXT = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
const NOMBRES_MESES_TXT = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
function diaDeLaSemana(fechaISO) { return NOMBRES_DIAS_TXT[new Date(fechaISO + 'T12:00:00').getDay()]; }
function fechaConDia(fechaISO) { const d = new Date(fechaISO + 'T12:00:00'); return NOMBRES_DIAS_TXT[d.getDay()] + ' ' + d.getDate() + ' de ' + NOMBRES_MESES_TXT[d.getMonth()]; }

// ==========================================================
// Turnos Disponibles - Procesamiento post-Merge
// ==========================================================

function toMinutes(hhmm) {
  if (!hhmm) return null;
  const match = String(hhmm).match(/(\d{1,2}):(\d{2})/);
  if (!match) return null;
  return parseInt(match[1], 10) * 60 + parseInt(match[2], 10);
}

function toHHMM(mins) {
  const h = String(Math.floor(mins / 60)).padStart(2, '0');
  const m = String(mins % 60).padStart(2, '0');
  return `${h}:${m}`;
}

function getFechaHoyArgentina() {
  return new Date().toLocaleDateString('en-CA', { timeZone: 'America/Argentina/Buenos_Aires' });
}

const DIAS_SEMANA = {
  domingo: 0,
  lunes: 1,
  martes: 2,
  miercoles: 3,
  jueves: 4,
  viernes: 5,
  sabado: 6
};

function normalizarTexto(str) {
  return str
    .toString()
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function esFechaPuntual(str) {
  return /^\d{4}-\d{2}-\d{2}$/.test(str.trim());
}

function fechaCoincideConFiltro(fecha, fechaEspecifica) {
  if (!fechaEspecifica) return true;

  if (esFechaPuntual(fechaEspecifica)) {
    return fecha === fechaEspecifica.trim();
  }

  const diaTexto = normalizarTexto(fechaEspecifica);
  if (Object.prototype.hasOwnProperty.call(DIAS_SEMANA, diaTexto)) {
    const diaSemanaFecha = new Date(`${fecha}T00:00:00`).getDay();
    return diaSemanaFecha === DIAS_SEMANA[diaTexto];
  }

  return true;
}

const MARGEN_HORA_ESPECIFICA_MINUTOS = 10;

function horaCoincideConFiltro(horarioRecepcion, horaEspecifica) {
  if (!horaEspecifica) return true;

  // Si viene con operador (">08:15", "<=12:00"...), ya se filtró en Asesores Disponibles
  if (/^\s*(>=|<=|>|<)/.test(horaEspecifica)) return true;

  const minSlot = toMinutes(horarioRecepcion);
  const minFiltro = toMinutes(horaEspecifica);
  if (minSlot === null || minFiltro === null) return false;

  return Math.abs(minSlot - minFiltro) <= MARGEN_HORA_ESPECIFICA_MINUTOS;
}

// ---------- Configuración ----------
const DURACION_SERVICIO_MINUTOS = 60;
const DIFERENCIA_MAXIMA_MINUTOS = 60;
const MAX_TURNOS_POR_DIA_GENERAL = 2;        // búsqueda general (varios días)
const MAX_TURNOS_POR_DIA_FECHA_PUNTUAL = 4;  // cuando piden un día específico
const fechaHoy = getFechaHoyArgentina();

// ---------- Obtener filtros opcionales del trigger ----------
let fechaEspecifica = null;
let horaEspecifica = null;
try {
  const trigger = $('When Executed by Another Workflow').first()?.json || {};
  fechaEspecifica = (trigger.fechaEspecifica || '').toString().trim() || null;
  horaEspecifica = (trigger.horaEspecifica || '').toString().trim() || null;
} catch (e) {}

// Si piden una fecha puntual (ej: "2026-10-05") se ofrecen 4 turnos; si no, 2 por día
const MAX_TURNOS_POR_DIA = (fechaEspecifica && esFechaPuntual(fechaEspecifica))
  ? MAX_TURNOS_POR_DIA_FECHA_PUNTUAL
  : MAX_TURNOS_POR_DIA_GENERAL;

// ---------- Separar items que llegan desde el Merge ----------
const itemsCombinados = $input.all().map(i => i.json);

const listaAsesores = itemsCombinados.filter(item => item.detalleAsesores || item.totalAsesoresConDisponibilidad !== undefined);
const listaMecanicos = itemsCombinados.filter(item => item.huecosLibres || item.servicios || item.specialtyIds);

// Indexar mecánicos de Mantenimiento disponibles por fecha
const agendaMecanicos = {};
for (const m of listaMecanicos) {
  const f = m.fecha || m.fechaActual;
  if (!f) continue;

  const servicios = (m.servicios || []).map(s => normalizarTexto(s));
  const specialtyIds = m.specialtyIds || [];

  const haceMantenimiento =
    specialtyIds.includes(5) || specialtyIds.includes(111) || servicios.some(s => s.includes("mantenimiento"));

  if (!haceMantenimiento) continue;

  if (!agendaMecanicos[f]) {
    agendaMecanicos[f] = [];
  }

  const intervalos = [];
  (m.huecosLibres || []).forEach(rango => {
    const partes = rango.split(/[-–—]/).map(s => s.trim());
    if (partes.length === 2) {
      const ini = toMinutes(partes[0]);
      const fin = toMinutes(partes[1]);
      if (ini !== null && fin !== null) {
        intervalos.push([ini, fin]);
      }
    }
  });

  agendaMecanicos[f].push({
    nombre: m.advisorName,
    intervalos
  });
}

const turnosDisponibles = [];
const turnosPorFecha = {};

// Cruzar disponibilidad Asesor - Mecánico
for (const diaAsesor of listaAsesores) {
  const fecha = diaAsesor.fecha || diaAsesor.fechaActual;
  if (!fecha) continue;

  if (fecha === fechaHoy) continue;
  if (!fechaCoincideConFiltro(fecha, fechaEspecifica)) continue;

  const mecanicosDelDia = agendaMecanicos[fecha] || [];
  if (mecanicosDelDia.length === 0) continue;

  if (!turnosPorFecha[fecha]) turnosPorFecha[fecha] = 0;

  for (const asesor of (diaAsesor.detalleAsesores || [])) {
    if (turnosPorFecha[fecha] >= MAX_TURNOS_POR_DIA) break;

    for (const slotRecepcion of (asesor.slotsDisponibles || [])) {
      if (turnosPorFecha[fecha] >= MAX_TURNOS_POR_DIA) break;

      const minRecepcion = toMinutes(slotRecepcion);

      if (!horaCoincideConFiltro(slotRecepcion, horaEspecifica)) continue;

      let asignado = false;

      for (const mec of mecanicosDelDia) {
        if (asignado) break;

        for (let i = 0; i < mec.intervalos.length; i++) {
          const [iniMec, finMec] = mec.intervalos[i];

          const inicioAtencion = Math.max(minRecepcion, iniMec);
          const finAtencion = inicioAtencion + DURACION_SERVICIO_MINUTOS;
          const diferenciaEspera = inicioAtencion - minRecepcion;

          if (
            diferenciaEspera >= 0 &&
            diferenciaEspera <= DIFERENCIA_MAXIMA_MINUTOS &&
            finAtencion <= finMec
          ) {
            turnosDisponibles.push({
              json: {
                fecha,
                diaSemana: diaDeLaSemana(fecha),
                fechaTexto: fechaConDia(fecha),
                horarioRecepcion: slotRecepcion,
                asesorId: asesor.advisorId,
                asesorNombre: asesor.advisorName,
                mecanicoNombre: mec.nombre,
                huecoMecanico: `${toHHMM(inicioAtencion)} - ${toHHMM(finAtencion)}`,
                diferenciaEsperaMinutos: diferenciaEspera
              }
            });

            turnosPorFecha[fecha]++;

            // Descontar intervalo consumido del mecánico
            const nuevosIntervalos = [];
            if (inicioAtencion > iniMec) {
              nuevosIntervalos.push([iniMec, inicioAtencion]);
            }
            if (finMec > finAtencion) {
              nuevosIntervalos.push([finAtencion, finMec]);
            }
            mec.intervalos.splice(i, 1, ...nuevosIntervalos);

            asignado = true;
            break;
          }
        }
      }
    }
  }
}

if (turnosDisponibles.length === 0) {
  return [{
    json: {
      turnosEncontrados: 0,
      mensaje: "No hay turnos disponibles para los filtros solicitados"
    }
  }];
}

return turnosDisponibles;

const fechaActual = $('Loop Over Items5').item.json.date;

function toMinutes(hhmm) {
  if (!hhmm) return null;
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

function toHHMM(mins) {
  const h = String(Math.floor(mins / 60)).padStart(2, '0');
  const m = String(mins % 60).padStart(2, '0');
  return `${h}:${m}`;
}

function generarSlots(entry, exit, interval) {
  const inicio = toMinutes(entry);
  const fin = toMinutes(exit);
  if (inicio === null || fin === null) return [];

  const slots = [];
  for (let t = inicio; t < fin; t += interval) {
    slots.push(toHHMM(t));
  }
  return slots;
}

const inputData = $input.first()?.json?.result?.advisorDealerSchedule;
const interval = inputData?.interval || 20;
const advisors = inputData?.advisors || [];

const resultado = advisors.map(a => {
  const gridCompleto = [
    ...generarSlots(a.amEntrance, a.amExit, interval),
    ...generarSlots(a.pmEntrance, a.pmExit, interval)
  ];

  // 1. Filtrar daysOffs aplicables para la fecha actual
  const daysOffActivos = (a.daysOffs || []).filter(off => {
    return fechaActual >= off.startDay && fechaActual <= off.endDay;
  });

  const slotsBloqueadosSet = new Set();

  // Si tiene descanso todo el día, se bloquean todos los slots de su jornada
  const tieneDiaLibreCompleto = daysOffActivos.some(off => off.allDay);
  if (tieneDiaLibreCompleto) {
    gridCompleto.forEach(s => slotsBloqueadosSet.add(s));
  } else {
    // Bloqueos por franja horaria de daysOffs
    daysOffActivos.forEach(off => {
      if (off.offStartHour && off.offEndHour) {
        const slotsOff = generarSlots(off.offStartHour, off.offEndHour, interval);
        slotsOff.forEach(s => slotsBloqueadosSet.add(s));
      }
    });
  }

  // 2. Bloqueos por nonScheduled (sin cita)
  (a.nonScheduled || []).forEach(s => {
    if (s.passerbyHour) slotsBloqueadosSet.add(s.passerbyHour);
  });

  // Ordenar los slots bloqueados
  const slotsOcupados = Array.from(slotsBloqueadosSet).sort((a, b) => toMinutes(a) - toMinutes(b));

  return {
    json: {
      fechaActual,
      advisorId: a.advisorId,
      advisorName: a.advisorName,
      Slots_Bloqueados: slotsOcupados,
      Cantidad_Slots_Bloqueados: slotsOcupados.length
    }
  };
});

if (resultado.length === 0) {
  return [{
    json: {
      fechaActual,
      vacio: true,
      Slots_Bloqueados: [],
      Cantidad_Slots_Bloqueados: 0
    }
  }];
}

return resultado;

