// Code13 - Selección de 1 Único Mecánico de Mantenimiento + Asesor de Recepción
// ==========================================================

function toMinutes(hhmm) {
  if (!hhmm) return null;
  const match = String(hhmm).match(/(\d{1,2}):(\d{2})/);
  if (!match) return null;
  return parseInt(match[1], 10) * 60 + parseInt(match[2], 10);
}

function toHHMM(mins) {
  const h = String(Math.floor(mins / 60)).padStart(2, '0');
  const m = String(mins % 60).padStart(2, '0');
  return `${h}:${m}`;
}

const norm = (v) => String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

const ADVISOR_ID_FALLBACK = 146715; // "Servicio Móvil" — se usa cuando no se puede resolver ningún asesor

// 1. Obtener datos del trigger y de la tabla seleccionada
let trigger = {};
try {
  trigger = $('When Executed by Another Workflow').first()?.json || {};
} catch (e) {}

let tabla = {};
try {
  tabla = $('Select rows from a table4').first()?.json || {};
} catch (e) {}

const fechaActual = trigger.fechaElegida || trigger.date || tabla.selected_date || "2026-09-08";
const horaRecepcionStr = trigger.hour || trigger.selected_hour || tabla.selected_hour || "12:40";
const horaRecepcionMin = toMinutes(horaRecepcionStr);
const nombreAsesorElegido = trigger.nombre_asesor || tabla.advisorName || null;
const esGralPico =
  String(trigger.gralPico || tabla.gralPico || "").toLowerCase() === "si" ||
  norm(trigger.resumen).includes('general pico') ||
  norm(nombreAsesorElegido).includes('gral pico') ||
  norm(nombreAsesorElegido).includes('general pico');
const NOMBRES_MECANICOS_GRAL_PICO = ["NAZARENO ALE", "FEDERICO MAURICHAU"];

// 2. Extraer especialistas y schedules del input
const inputItem = $input.all()[0]?.json;
const data = inputItem?.result || inputItem;
const specialists = data?.technicalSpecialists || [];
const schedules = data?.schedules || [];

const mecanicosCalculados = [];

for (const esp of specialists) {
  const specialtyIds = (esp.specialties || []).map(s => s.id);
  const serviciosNombres = (esp.specialties || []).map(s => s.name);

  if (esGralPico) {
    const esMecanicoGralPico = NOMBRES_MECANICOS_GRAL_PICO.some(n => (esp.advisorName || "").toUpperCase().includes(n));
    if (!esMecanicoGralPico) continue;
  } else {
    const esDeMantenimiento = specialtyIds.includes(5) || serviciosNombres.some(s => s.toLowerCase().includes("mantenimiento"));
    if (!esDeMantenimiento) continue;
  }

  const firstShift = esp.workSchedule?.firstShift;
  const secondShift = esp.workSchedule?.secondShift;

  if (esp.availability?.totallyUnavailable || (!firstShift && !secondShift)) continue;

  const unavailableList = esp.availability?.unavailableTimes || esp.availability?.unavailablePeriods || [];
  const bloqueosIndisponibilidad = unavailableList
    .map(p => {
      const ini = toMinutes(p.startTime || p.start || p.entry);
      const fin = toMinutes(p.endTime || p.end || p.exit);
      return (ini !== null && fin !== null) ? [ini, fin] : null;
    })
    .filter(Boolean);

  const citasAgendadas = schedules
    .filter(s => s.productiveId === esp.advisorId || s.advisorId === esp.advisorId)
    .map(s => {
      const ini = toMinutes(s.startTime || s.start);
      const fin = toMinutes(s.endTime || s.end);
      return (ini !== null && fin !== null) ? [ini, fin] : null;
    })
    .filter(Boolean);

  const ocupados = [...bloqueosIndisponibilidad, ...citasAgendadas].sort((a, b) => a[0] - b[0]);

  const turnosTrabajo = [];
  if (firstShift?.entry && firstShift?.exit) {
    turnosTrabajo.push([toMinutes(firstShift.entry), toMinutes(firstShift.exit)]);
  }
  if (secondShift?.entry && secondShift?.exit) {
    turnosTrabajo.push([toMinutes(secondShift.entry), toMinutes(secondShift.exit)]);
  }

  const huecos = [];
  for (const [inicioTurno, finTurno] of turnosTrabajo) {
    let cursor = inicioTurno;
    for (const [ini, fin] of ocupados) {
      if (fin <= cursor || ini >= finTurno) continue;
      if (ini > cursor) huecos.push([cursor, Math.min(ini, finTurno)]);
      cursor = Math.max(cursor, fin);
    }
    if (cursor < finTurno) huecos.push([cursor, finTurno]);
  }

  const DURACION_SERVICIO = 60;
  const DIFERENCIA_MAXIMA = 60;

  for (const [iniHueco, finHueco] of huecos) {
    const inicioAtencion = Math.max(horaRecepcionMin, iniHueco);
    const finAtencion = inicioAtencion + DURACION_SERVICIO;
    const diffEspera = inicioAtencion - horaRecepcionMin;

    if (diffEspera >= 0 && diffEspera <= DIFERENCIA_MAXIMA && finAtencion <= finHueco) {
      mecanicosCalculados.push({
        fecha: fechaActual,
        horarioRecepcion: horaRecepcionStr,
        asesorNombre: nombreAsesorElegido,
        mecanicoId: esp.advisorId,
        mecanicoNombre: esp.advisorName,
        servicios: serviciosNombres,
        specialtyIds: specialtyIds,
        productiveAttendanceHour: toHHMM(inicioAtencion),
        productiveAttendanceEndHour: toHHMM(finAtencion),
        huecoMecanico: `${toHHMM(inicioAtencion)} - ${toHHMM(finAtencion)}`,
        diferenciaEsperaMinutos: diffEspera
      });
      break;
    }
  }
}

if (mecanicosCalculados.length === 0) {
  return [{
    json: {
      fecha: fechaActual,
      horarioRecepcion: horaRecepcionStr,
      encontrado: false,
      mensaje: "No se encontraron mecánicos de mantenimiento disponibles en el rango horario solicitado"
    }
  }];
}

mecanicosCalculados.sort((a, b) => a.diferenciaEsperaMinutos - b.diferenciaEsperaMinutos);
const mejorMecanico = mecanicosCalculados[0];

