// ==========================================================
// Code34 - Payload para crear el turno a partir de "Turno ofrecido"
// ==========================================================
const CREATE_USER = 'V-MOURE2';
const SUCURSALES = { '74': 'Rosario', '60064': 'San Nicolás' };
const NOMBRE_GRAL_PICO = 'General Pico — Servicio Móvil';
const IDS_MANTENIMIENTO = [5, 111];

function toHourNumber(hora) { return Number(String(hora).trim().replace(':', '')); }
function cleanHHMM(hora)   { return String(hora).trim().replace(':', '').padStart(4, '0'); }
function getCreateSTimestamp() {
  const now = new Date();
  return `${now.toISOString().slice(0, 19)}.${String(now.getMilliseconds()).padStart(3, '0')}0`;
}
const norm = (v) => String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();

// 1. Nodos de origen de datos
const turno = $('Turno ofrecido').first().json;
const tabla = $('Select rows from a table4').first().json;
const trigger = $('When Executed by Another Workflow').first().json;
const cotizacionNode = $('HTTP Request33').first().json;
const especialistas = $('HTTP Request').first().json?.result?.technicalSpecialists || [];

// Si no se encontró el turno ofrecido, no creamos nada
if (turno.turnosEncontrados === 0 || !turno.horarioRecepcion) {
  throw new Error(`No se encontró el turno ofrecido: ${turno.mensaje || 'sin datos'}`);
}

// 2. Horarios y Fechas
const scheduleDate = turno.fecha;
const scheduleHourNum = toHourNumber(turno.horarioRecepcion);

// 3. Asesor de recepción
const advisorId = Number(turno.asesorId);

// 4. Mecánico y Especialidad de Taller (se buscan por nombre en el HTTP Request de mecánicos)
const mecanico = especialistas.find(e => norm(e.advisorName) === norm(turno.mecanicoNombre));
if (!mecanico) {
  throw new Error(`No se encontró el ID del mecánico "${turno.mecanicoNombre}" en el HTTP Request`);
}
const productiveId = Number(mecanico.advisorId);

const [horaInicioMec, horaFinMec] = String(turno.huecoMecanico).split(/[-–—]/).map(s => s.trim());
const productiveAttendanceHour = cleanHHMM(horaInicioMec);
const productiveAttendanceEndHour = cleanHHMM(horaFinMec);

const specialtyIds = (mecanico.specialties || []).map(s => s.id);
const serviceTypeIdWorkshop = Number(
  specialtyIds.find(id => IDS_MANTENIMIENTO.includes(id)) ?? specialtyIds[0] ?? 5
);

// 5. Cotización y Servicios Ofrecidos
const quotationScheduleVO = cotizacionNode.result?.quotationScheduleVO || cotizacionNode.quotationScheduleVO;
const serviceIdComercial = Number(quotationScheduleVO.quotationVOs[0].serviceId);

// 6. Concesionario, Vehículo y Cliente
const dealerCode = Number(tabla.sucursal);
const customerId = Number(tabla.customerK);
const vehiclePlate = trigger.patente || tabla.plate || null;
const vehicleVin = tabla.chassi;
const modelGroup = Number(tabla.model_id);

// 6b. Concesionario al que asiste el cliente.
const esGralPico =
  norm(trigger.gralPico) === 'si' ||
  norm(trigger.resumen).includes('general pico') ||
  norm(trigger.nombre_asesor).includes('gral pico') ||
  norm(trigger.nombre_asesor).includes('general pico');
const nombreConcesionario = esGralPico
  ? NOMBRE_GRAL_PICO
  : (SUCURSALES[String(tabla.sucursal)] || `Sucursal ${tabla.sucursal}`);

const nombreCliente = [tabla.firstname, tabla.lastname].filter(Boolean).join(' ').trim();
const kmDeclarados = (String(trigger.resumen || '').match(/km declarados:\s*(\d(?:[\d.]*\d)?)/i) || [])[1];
const lastKm = kmDeclarados ? Number(String(kmDeclarados).replace(/\./g, '')) : null;

// 6b2. Nota del asistente sobre el precio (precio aproximado / circular / sin precio),
// guardada por get_detail_servicios en la data table notas_turno_af para este servicio
let notaAsistente = '';
try {
  const n = $('Nota AF').first().json || {};
  if (n.nota && (!n.service_id || Number(n.service_id) === Number(tabla.service_id))) notaAsistente = String(n.nota);
} catch (e) {}
// Si Ford no trae precio en el presupuesto (por ejemplo, turnos de un mes que todavía no tiene precios cargados),
// la nota del asesor lleva el precio que el bot le informó al cliente. Si Ford trae precio, esa nota no hace falta.
const precioFord = Number(quotationScheduleVO?.quotationVOs?.[0]?.price) > 0;
if (/Precio informado al cliente/i.test(notaAsistente) && precioFord) notaAsistente = '';
// Y en ese caso se carga en el presupuesto del turno el mismo precio, para que la Agenda no muestre "Precio a confirmar".
// Ford acepta el precio en centavos en price y discount (mismo formato que devuelve cuando tiene el precio).
// Precio que el bot le dijo al cliente, según la nota guardada:
//  - plan de Ford: "Precio informado al cliente: $575.680"
//  - fallback con precio de la circular: "Se le informó al cliente $333.950 según la circular"
//  - fallback con precio aproximado: "Se le informó como referencia el precio de <versión>: $589.680"
const notaTxt = String(notaAsistente);
const mPrecio = notaTxt.match(/Precio informado al cliente:\s*\$\s?([\d.,]+)/i)
  || notaTxt.match(/Se le inform[oó] al cliente\s*\$\s?([\d.,]+)/i)
  || notaTxt.match(/como referencia el precio de[^$]*\$\s?([\d.,]+)/i);
const qv = quotationScheduleVO?.quotationVOs?.[0];
if (!precioFord && mPrecio && qv) {
  const precioInformado = Number(String(mPrecio[1]).replace(/[^\d]/g, ''));
  if (precioInformado > 0) { qv.price = precioInformado * 100; qv.discount = precioInformado * 100; }
}

// 6c. Observaciones — customerRemark = bloque "Cliente", advisorRemark = bloque "Concesionario"
// Ford rechaza el turno con SCHEDULING.BAD_REQUEST si advisorRemark supera ~200 caracteres
// (probado el 18/11: 200 entra, 250 no). customerRemark acepta al menos 300.
const MAX_OBS_ASESOR = 200;
const MAX_OBS_CLIENTE = 300;
const limpiar = (s) => String(s || '').replace(/\s+/g, ' ').trim();
const recortar = (s, max) => (s.length <= max ? s : s.slice(0, max - 1).trimEnd() + '…');

const obsCliente = recortar(limpiar([
  String(trigger.resumen || '').trim(),
  `Concesionario: ${nombreConcesionario}.`,
  vehiclePlate ? `Patente: ${vehiclePlate}.` : '',
].filter(Boolean).join(' ')), MAX_OBS_CLIENTE);

// Para el asesor: primero lo imprescindible y la nota del precio; el resto se agrega solo si entra.
const notaCorta = limpiar(notaAsistente)
  .replace(/^\[Asistente\]\s*/, 'Asistente: ')
  .replace(/Ford no informó precio por API\.\s*/i, 'Ford sin precio. ')
  .replace(/Se le informó al cliente/i, 'Se informó al cliente')
  .replace(/según la circular de Ford/i, 'según circular Ford')
  .replace(/Precio informado al cliente:/i, 'Precio informado al cliente (Ford no lo trae):');
const obsBase = [
  'Turno del asistente de WhatsApp.',
  vehiclePlate ? `Patente: ${vehiclePlate}.` : '',
  kmDeclarados ? `KM: ${kmDeclarados}.` : '',
].filter(Boolean);
const obsOpcionales = [
  nombreCliente ? `Cliente: ${nombreCliente}.` : '',
  tabla.model ? `Vehículo: ${tabla.model}.` : '',
  `Concesionario: ${nombreConcesionario}.`,
].filter(Boolean);
let partesAsesor = notaCorta ? [...obsBase, notaCorta] : [...obsBase];
for (const p of obsOpcionales) {
  const prueba = notaCorta ? [...partesAsesor.slice(0, -1), p, notaCorta] : [...partesAsesor, p];
  if (limpiar(prueba.join(' ')).length <= MAX_OBS_ASESOR) partesAsesor = prueba;
}
const obsConcesionario = recortar(limpiar(partesAsesor.join(' ')), MAX_OBS_ASESOR);

// 7. Armado del payload con la estructura exacta de la API
const payload = {
  country: "ARG",
  dealer: dealerCode,
  division: 1,
  scheduleDate: scheduleDate,
  scheduleHour: scheduleHourNum,
  vin: vehicleVin,
  offeredServices: [serviceIdComercial],
  quotationScheduleVO: quotationScheduleVO,
  advisor: advisorId,
  createUser: CREATE_USER,
  sendEmail: true,
  contactCountry: "ARG",
  vehiclePlate: vehiclePlate,
  contactCustomerId: customerId,
  customerId: customerId,
  customerRemark: obsCliente,
  advisorRemark: obsConcesionario,
  isDriverInformation: null,
  scheduleSource: "D",
  scheduleType: "R",
  model: "",
  group: modelGroup,
  createS: getCreateSTimestamp(),
  campaignsId: [],
  lastKm: lastKm,
  oilLifeRemaining: null,
  iolmMonths: null,
  referredBy: 0,
  // Campos que pide Ford desde el 16/11 (sin ellos create-schedule-and-workshop devuelve SCHEDULING.NOT_FOUND)
  iolmParts: [],
  recallVOs: [],
  returned: "N",
  towTruckNeeded: "N",
  towTruckType: null,
  towingReason: null,
  scheduleWorkshop: [
    {
      openSchedule: false,
      noShow: false,
      productiveId: productiveId,
      productiveAttendanceHour: productiveAttendanceHour,
      productiveAttendanceEndHour: productiveAttendanceEndHour,
      productiveAttendance: scheduleDate,
      assignedService: [{ id: serviceTypeIdWorkshop, duration: 60 }],
      status: "SCHEDULED",
      statusSchedule: "SCHEDULED",
      delay: false,
      height: 138.88888888888889
    }
  ]
};

return [{ json: { body: payload } }];

const fechaActual = String($('Select rows from a table4').first().json.selected_date ?? '').slice(0, 10);

function toMinutes(hhmm) {
  if (!hhmm) return null;
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

function toHHMM(mins) {
  const h = String(Math.floor(mins / 60)).padStart(2, '0');
  const m = String(mins % 60).padStart(2, '0');
  return `${h}:${m}`;
}

const data = $input.first().json.result;
const specialists = data?.technicalSpecialists || [];
const schedules = data?.schedules || [];
const resultado = [];

for (const esp of specialists) {
  const specialtyIds = (esp.specialties || []).map(s => s.id);

  const firstShift = esp.workSchedule?.firstShift;
  const secondShift = esp.workSchedule?.secondShift;

  // Si está totalmente no disponible o no tiene turnos configurados
  if (esp.availability?.totallyUnavailable || (!firstShift && !secondShift)) {
    resultado.push({
      json: {
        fechaActual,
        advisorName: esp.advisorName,
        Huecos_Libres: [],
        specialtyIds
      }
    });
    continue;
  }

  // Obtenemos los bloqueos de indisponibilidad (soporta unavailableTimes y unavailablePeriods)
  const unavailableList = esp.availability?.unavailableTimes || esp.availability?.unavailablePeriods || [];

  const bloqueosIndisponibilidad = unavailableList
    .map(p => {
      const ini = toMinutes(p.startTime || p.start || p.entry);
      const fin = toMinutes(p.endTime || p.end || p.exit);
      return (ini !== null && fin !== null) ? [ini, fin] : null;
    })
    .filter(Boolean);

  // Obtenemos las citas ya agendadas
  const citasAgendadas = schedules
    .filter(s => s.productiveId === esp.advisorId || s.advisorId === esp.advisorId)
    .map(s => {
      const ini = toMinutes(s.startTime || s.start);
      const fin = toMinutes(s.endTime || s.end);
      return (ini !== null && fin !== null) ? [ini, fin] : null;
    })
    .filter(Boolean);

  // Unificamos y ordenamos todos los intervalos ocupados
  const ocupados = [...bloqueosIndisponibilidad, ...citasAgendadas].sort((a, b) => a[0] - b[0]);

  const turnosTrabajo = [];
  if (firstShift?.entry && firstShift?.exit) {
    turnosTrabajo.push([toMinutes(firstShift.entry), toMinutes(firstShift.exit)]);
  }
  if (secondShift?.entry && secondShift?.exit) {
    turnosTrabajo.push([toMinutes(secondShift.entry), toMinutes(secondShift.exit)]);
  }

  const huecos = [];
  for (const [inicioTurno, finTurno] of turnosTrabajo) {
    let cursor = inicioTurno;
    for (const [ini, fin] of ocupados) {
      if (fin <= cursor || ini >= finTurno) continue;
      if (ini > cursor) {
        huecos.push([cursor, Math.min(ini, finTurno)]);
      }
      cursor = Math.max(cursor, fin);
    }
    if (cursor < finTurno) {
      huecos.push([cursor, finTurno]);
    }
  }

  resultado.push({
    json: {
      fechaActual,
      advisorName: esp.advisorName,
      Huecos_Libres: huecos.map(([ini, fin]) => `${toHHMM(ini)} - ${toHHMM(fin)}`),
      specialtyIds
    }
  });
}

return resultado;

const fechaActual = String($('Select rows from a table4').first().json.selected_date ?? '').slice(0, 10);

function toMinutes(hhmm) {
  if (!hhmm) return null;
  const [h, m] = String(hhmm).trim().split(':').map(Number);
  return h * 60 + m;
}

function toHHMM(mins) {
  const h = String(Math.floor(mins / 60)).padStart(2, '0');
  const m = String(mins % 60).padStart(2, '0');
  return `${h}:${m}`;
}

function generarSlots(entry, exit, interval) {
  const inicio = toMinutes(entry);
  const fin = toMinutes(exit);
  if (inicio === null || fin === null) return [];

  const slots = [];
  for (let t = inicio; t < fin; t += interval) {
    slots.push(toHHMM(t));
  }
  return slots;
}

// Juntamos los asesores de TODOS los items de entrada (sin duplicar por advisorId)
let interval = 20;
const advisorsPorId = new Map();

for (const item of $input.all()) {
  let raw = item.json;
  if (Array.isArray(raw)) raw = raw[0];
  const data = raw?.result?.advisorDealerSchedule ?? raw?.advisorDealerSchedule;
  if (!data) continue;

  interval = Number(data.interval) || interval;

  for (const a of (data.advisors || [])) {
    const previo = advisorsPorId.get(a.advisorId);
    if (!previo) {
      advisorsPorId.set(a.advisorId, {
        ...a,
        daysOffs: [...(a.daysOffs || [])],
        nonScheduled: [...(a.nonScheduled || [])],
        dealerSchedule: [...(a.dealerSchedule || [])]
      });
    } else {
      previo.daysOffs.push(...(a.daysOffs || []));
      previo.nonScheduled.push(...(a.nonScheduled || []));
      previo.dealerSchedule.push(...(a.dealerSchedule || []));
    }
  }
}

const advisors = [...advisorsPorId.values()];

const resultado = advisors.map(a => {
  // 1. Días libres / Ausencias activas ese día
  const daysOffActivos = (a.daysOffs || []).filter(off => {
    return fechaActual >= off.startDay && fechaActual <= off.endDay;
  });

  // Si tiene día libre completo, 0 disponibles
  if (daysOffActivos.some(off => off.allDay)) {
    return {
      json: {
        fechaActual,
        advisorId: a.advisorId,
        advisorName: a.advisorName,
        Slots_Libres: [],
        Cantidad_Slots_Libres: 0
      }
    };
  }

  // Sets de exclusión
  const slotsDaysOff = new Set();
  daysOffActivos.forEach(off => {
    if (off.offStartHour && off.offEndHour) {
      generarSlots(off.offStartHour, off.offEndHour, interval).forEach(s => slotsDaysOff.add(s));
    }
  });

  const reservadosSinCita = new Set((a.nonScheduled || []).map(s => s.passerbyHour));

  const asignados = new Set(
    (a.dealerSchedule || [])
      .filter(s => s.dateSchedule === fechaActual)
      .map(s => s.hourSchedule)
  );

  // 2. Grilla base de jornada
  const gridCompleto = [
    ...generarSlots(a.amEntrance, a.amExit, interval),
    ...generarSlots(a.pmEntrance, a.pmExit, interval)
  ];

  // 3. Filtrar turnos disponibles
  const slotsLibres = gridCompleto.filter(h =>
    !reservadosSinCita.has(h) &&
    !asignados.has(h) &&
    !slotsDaysOff.has(h)
  );

  return {
    json: {
      fechaActual,
      advisorId: a.advisorId,
      advisorName: a.advisorName,
      Slots_Libres: slotsLibres,
      Cantidad_Slots_Libres: slotsLibres.length
    }
  };
});

if (resultado.length === 0) {
  return [{
    json: {
      fechaActual,
      vacio: true,
      Slots_Libres: [],
      Cantidad_Slots_Libres: 0
    }
  }];
}

return resultado;

const items = $input.all().map(i => i.json);

function toMinutes(hhmm) {
  if (!hhmm) return null;
  const [h, m] = hhmm.trim().split(':').map(Number);
  return h * 60 + m;
}

function toHHMM(minutes) {
  const h = Math.floor(minutes / 60).toString().padStart(2, '0');
  const m = (minutes % 60).toString().padStart(2, '0');
  return `${h}:${m}`;
}

const MAPA_SERVICIOS = {
  5: 'Mantenimiento',
  14: 'Taller Móvil',
  111: 'Mantenimiento - Kit IOLM',
  112: 'Reparación',
  113: 'Campañas De Servicio',
  114: 'Diagnóstico',
  115: 'Servicios Generales',
  116: 'Accesorios',
  117: 'Lavado',
  118: 'Colisión'
};

// Ids de specialty que cuentan como "hace Mantenimiento"
const IDS_MANTENIMIENTO = [5, 111];

const DURACION_TURNO_MINUTOS = 60;
const HORA_APERTURA = toMinutes('08:00');
const HORA_CIERRE   = toMinutes('17:00'); // último turno posible: 16:00-17:00

const resultado = [];

for (const item of items) {
  const fecha = item.fechaActual || item.fecha;
  const advisorName = item.advisorName || item.mecanicoNombre;
  const huecosEntrada = item.Huecos_Libres || item.huecosLibres || [];

  let servicios = item.servicios || [];
  if (servicios.length === 0 && Array.isArray(item.specialtyIds)) {
    servicios = item.specialtyIds.map(id => MAPA_SERVICIOS[id]).filter(Boolean);
  }

  // Solo mecánicos de Mantenimiento
  const haceMantenimiento = (item.specialtyIds && item.specialtyIds.some(id => IDS_MANTENIMIENTO.includes(id))) ||
    servicios.some(s => s.toLowerCase().includes('mantenimiento'));
  if (!haceMantenimiento) continue;

  // Parseamos los rangos libres una sola vez
  const rangosLibres = huecosEntrada
    .filter(r => r && r.includes('-'))
    .map(r => {
      const [ini, fin] = r.split('-').map(s => s.trim());
      return { ini: toMinutes(ini), fin: toMinutes(fin) };
    })
    .filter(r => r.ini !== null && r.fin !== null && r.fin > r.ini);

  const bloquesDisponibles = [];

  // Recorremos SIEMPRE la grilla fija en punto (08:00, 09:00, 10:00...)
  for (
    let slotInicio = HORA_APERTURA;
    slotInicio + DURACION_TURNO_MINUTOS <= HORA_CIERRE;
    slotInicio += DURACION_TURNO_MINUTOS
  ) {
    const slotFin = slotInicio + DURACION_TURNO_MINUTOS;
    // El slot solo es válido si cae COMPLETO dentro de algún hueco libre
    const cabeEnAlgunHueco = rangosLibres.some(r => r.ini <= slotInicio && r.fin >= slotFin);
    if (cabeEnAlgunHueco) {
      bloquesDisponibles.push(`${toHHMM(slotInicio)} - ${toHHMM(slotFin)}`);
    }
  }

  if (bloquesDisponibles.length > 0) {
    resultado.push({
      json: {
        fecha,
        advisorName,
        servicios,
        huecosLibres: bloquesDisponibles
      }
    });
  }
}

return resultado;

const items = $input.all().map(i => i.json);

// Objeto para agrupar por fecha
const agrupadoPorFecha = {};

for (const item of items) {
  // Ignoramos registros vacíos o sin slots disponibles
  if (item.vacio || !item.Slots_Libres || item.Slots_Libres.length === 0) continue;

  const fecha = item.fechaActual;

  if (!agrupadoPorFecha[fecha]) {
    agrupadoPorFecha[fecha] = {
      fecha: fecha,
      asesores: [],
      todosLosSlotsDeLaFecha: new Set()
    };
  }

  agrupadoPorFecha[fecha].asesores.push({
    advisorId: item.advisorId,
    advisorName: item.advisorName,
    slotsDisponibles: item.Slots_Libres,
    cantidadSlots: item.Cantidad_Slots_Libres
  });

  // Consolidamos todos los horarios únicos disponibles en el día
  item.Slots_Libres.forEach(slot => agrupadoPorFecha[fecha].todosLosSlotsDeLaFecha.add(slot));
}

// Formateamos la salida para n8n
return Object.values(agrupadoPorFecha).map(f => ({
  json: {
    fecha: f.fecha,
    totalAsesoresConDisponibilidad: f.asesores.length,
    slotsUnicosDelDia: Array.from(f.todosLosSlotsDeLaFecha).sort(),
    detalleAsesores: f.asesores
  }
}));

const fechaActual = String($('Select rows from a table4').first().json.selected_date ?? '').slice(0, 10);

function toMinutes(hhmm) {
  if (!hhmm) return null;
  const [h, m] = String(hhmm).trim().split(':').map(Number);
  return h * 60 + m;
}

function toHHMM(mins) {
  const h = String(Math.floor(mins / 60)).padStart(2, '0');
  const m = String(mins % 60).padStart(2, '0');
  return `${h}:${m}`;
}

function generarSlots(entry, exit, interval) {
  const inicio = toMinutes(entry);
  const fin = toMinutes(exit);
  if (inicio === null || fin === null) return [];

  const slots = [];
  for (let t = inicio; t < fin; t += interval) {
    slots.push(toHHMM(t));
  }
  return slots;
}

// El input puede llegar como objeto { error, result } o como array [{ error, result }]
let raw = $input.first()?.json;
if (Array.isArray(raw)) raw = raw[0];
const inputData = raw?.result?.advisorDealerSchedule ?? raw?.advisorDealerSchedule;
const interval = Number(inputData?.interval) || 20;
const advisors = inputData?.advisors || [];

const resultado = advisors.map(a => {
  const gridCompleto = [
    ...generarSlots(a.amEntrance, a.amExit, interval),
    ...generarSlots(a.pmEntrance, a.pmExit, interval)
  ];

  // 1. Filtrar daysOffs aplicables para la fecha elegida
  const daysOffActivos = (a.daysOffs || []).filter(off => {
    return fechaActual >= off.startDay && fechaActual <= off.endDay;
  });

  const slotsBloqueadosSet = new Set();

  // Si tiene descanso todo el día, se bloquean todos los slots de su jornada
  const tieneDiaLibreCompleto = daysOffActivos.some(off => off.allDay);
  if (tieneDiaLibreCompleto) {
    gridCompleto.forEach(s => slotsBloqueadosSet.add(s));
  } else {
    // Bloqueos por franja horaria de daysOffs
    daysOffActivos.forEach(off => {
      if (off.offStartHour && off.offEndHour) {
        const slotsOff = generarSlots(off.offStartHour, off.offEndHour, interval);
        slotsOff.forEach(s => slotsBloqueadosSet.add(s));
      }
    });
  }

  // 2. Bloqueos por nonScheduled (sin cita)
  (a.nonScheduled || []).forEach(s => {
    if (s.passerbyHour) slotsBloqueadosSet.add(s.passerbyHour);
  });

  // Ordenar los slots bloqueados
  const slotsOcupados = Array.from(slotsBloqueadosSet).sort((a, b) => toMinutes(a) - toMinutes(b));

  return {
    json: {
      fechaActual,
      advisorId: a.advisorId,
      advisorName: a.advisorName,
      Slots_Bloqueados: slotsOcupados,
      Cantidad_Slots_Bloqueados: slotsOcupados.length
    }
  };
});

if (resultado.length === 0) {
  return [{
    json: {
      fechaActual,
      vacio: true,
      Slots_Bloqueados: [],
      Cantidad_Slots_Bloqueados: 0
    }
  }];
}

return resultado;

// ==========================================================
// Turnos Disponibles 1 - Buscar el turno que eligió el cliente
// (misma fecha, misma hora y mismo asesor que se le ofreció)
// ==========================================================

function toMinutes(hhmm) {
  if (!hhmm) return null;
  const match = String(hhmm).match(/(\d{1,2}):(\d{2})/);
  if (!match) return null;
  return parseInt(match[1], 10) * 60 + parseInt(match[2], 10);
}

function toHHMM(mins) {
  const h = String(Math.floor(mins / 60)).padStart(2, '0');
  const m = String(mins % 60).padStart(2, '0');
  return `${h}:${m}`;
}

function normalizarTexto(str) {
  return String(str ?? '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ');
}

// ---------- Configuración ----------
const DURACION_SERVICIO_MINUTOS = 60;
const DIFERENCIA_MAXIMA_MINUTOS = 60;

// ---------- Turno elegido por el cliente ----------
const fila = $('Select rows from a table4').first().json;
const trigger = $('When Executed by Another Workflow').first().json;

const fechaElegida = String(fila.selected_date ?? '').slice(0, 10);
const minHoraElegida = toMinutes(fila.selected_hour);
const asesorIdElegido = fila.advisorId ?? null;
const asesorNombreElegido = normalizarTexto(trigger.nombre_asesor);

function esAsesorElegido(asesor) {
  if (asesorIdElegido != null && String(asesor.advisorId) === String(asesorIdElegido)) return true;
  return asesorNombreElegido !== '' && normalizarTexto(asesor.advisorName) === asesorNombreElegido;
}

// ---------- Separar items que llegan desde el Merge ----------
const itemsCombinados = $input.all().map(i => i.json);

const listaAsesores = itemsCombinados.filter(item => item.detalleAsesores || item.totalAsesoresConDisponibilidad !== undefined);
const listaMecanicos = itemsCombinados.filter(item => item.huecosLibres || item.servicios || item.specialtyIds);

// Mecánicos de Mantenimiento disponibles en la fecha elegida
const mecanicosDelDia = [];
for (const m of listaMecanicos) {
  const f = m.fecha || m.fechaActual;
  if (f !== fechaElegida) continue;

  const servicios = (m.servicios || []).map(s => normalizarTexto(s));
  const specialtyIds = m.specialtyIds || [];
  const haceMantenimiento =
    specialtyIds.includes(5) || specialtyIds.includes(111) || servicios.some(s => s.includes('mantenimiento'));
  if (!haceMantenimiento) continue;

  const intervalos = [];
  (m.huecosLibres || []).forEach(rango => {
    const partes = rango.split(/[-–—]/).map(s => s.trim());
    if (partes.length === 2) {
      const ini = toMinutes(partes[0]);
      const fin = toMinutes(partes[1]);
      if (ini !== null && fin !== null) intervalos.push([ini, fin]);
    }
  });

  mecanicosDelDia.push({ nombre: m.advisorName, intervalos });
}

// Buscar el turno: fecha + hora + asesor elegidos, con un mecánico que lo tome
let turno = null;

const diaAsesor = listaAsesores.find(d => (d.fecha || d.fechaActual) === fechaElegida);
const asesor = (diaAsesor?.detalleAsesores || []).find(esAsesorElegido);
const slotRecepcion = (asesor?.slotsDisponibles || []).find(s => toMinutes(s) === minHoraElegida);

if (slotRecepcion) {
  const minRecepcion = toMinutes(slotRecepcion);

  for (const mec of mecanicosDelDia) {
    for (const [iniMec, finMec] of mec.intervalos) {
      const inicioAtencion = Math.max(minRecepcion, iniMec);
      const finAtencion = inicioAtencion + DURACION_SERVICIO_MINUTOS;
      const diferenciaEspera = inicioAtencion - minRecepcion;

      if (diferenciaEspera <= DIFERENCIA_MAXIMA_MINUTOS && finAtencion <= finMec) {
        turno = {
          fecha: fechaElegida,
          horarioRecepcion: slotRecepcion,
          asesorId: asesor.advisorId,
          asesorNombre: asesor.advisorName,
          mecanicoNombre: mec.nombre,
          huecoMecanico: `${toHHMM(inicioAtencion)} - ${toHHMM(finAtencion)}`,
          diferenciaEsperaMinutos: diferenciaEspera
        };
        break;
      }
    }
    if (turno) break;
  }
}

if (!turno) {
  return [{
    json: {
      turnosEncontrados: 0,
      fecha: fechaElegida,
      hora: toHHMM(minHoraElegida ?? 0),
      asesor: trigger.nombre_asesor ?? null,
      mensaje: !asesor
        ? 'El asesor elegido no tiene disponibilidad ese día'
        : !slotRecepcion
          ? 'El horario elegido ya no está libre para ese asesor'
          : 'No hay mecánico disponible para ese horario'
    }
  }];
}

return [{ json: turno }];

// ============================================================
// Servicio con precio de la circular de Ford (fallback)
// Se llega acá cuando la API de Ford (revision/v2) NO devolvió un precio usable:
//   - no devolvió ningún servicio (km por encima del plan oficial),
//   - devolvió el servicio pero sin precio (0 / vacío / fuera de vigencia), o
//   - la llamada falló.
// 1) Servicio a reservar: el que devolvió Ford si lo hay; si no, se busca en el
//    catálogo del concesionario la "Nª Revisión de Mantenimiento" o, en su defecto,
//    "Cambio de Aceite y Filtros".
// 2) Precio: tabla precios_fuera_de_plan (circular de Ford del mes, PDF), por modelo
//    (groupR o nombre), motor (según Ford) y año del VIN:
//      PROGRAMADO -> precio según el km (precios_km, uno por intervalo de km_intervalo)
//      IOLM / MOTORCRAFT -> precio fijo (cuando el km supera la tabla programada)
//    Si no hay coincidencia vigente o hay dos precios distintos posibles -> sin precio.
// ============================================================
const norm = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toLowerCase().replace(/\s+/g, ' ').trim();
const sinParentesis = (s) => norm(String(s ?? '').replace(/\([^)]*\)/g, ''));

const fila = $('Select rows from a table2').first().json;
const calc = $('Code27').first().json;

// ---------- Respuesta original de Ford ----------
let revJson = {};
try { revJson = $('HTTP Request Ford Revision v2').first().json || {}; } catch (e) {}
const revResp = Array.isArray(revJson.response) ? revJson.response : [];
const dia = (v) => { const d = new Date(v); if (isNaN(d.getTime())) return null; d.setHours(0, 0, 0, 0); return d; };
const hoyDia = new Date(); hoyDia.setHours(0, 0, 0, 0);
const servicioVigente = revResp.find(s => {
  const a = dia(s.modelStartDate), b = dia(s.modelEndDate);
  return a && b && a <= hoyDia && hoyDia <= b;
}) || null;
const servicioDeFord = servicioVigente || revResp[0] || null;
const motivo = revJson.error ? 'ford_error' : (revResp.length ? 'ford_sin_precio' : 'ford_sin_servicio');

let motorFord = '';
try {
  const resp = $('Ford - motor del vehiculo').first().json.response || [];
  motorFord = String((resp[resp.length - 1] || {}).motorDescription || '');
} catch (e) {}
if (!motorFord && servicioDeFord) motorFord = String(servicioDeFord.motorDescription || '');
// Motor/versión que eligió el cliente (lo manda el agente cuando Ford no informa el motor)
let motorCliente = '';
try { motorCliente = String($('When Executed by Another Workflow').first().json.motor || '').trim(); } catch (e) {}
// "OTRA: <lo que dijo el cliente>" = el cliente dijo que su versión no es ninguna de las ofrecidas
const esOtraVersion = /^otra\b/i.test(motorCliente);
const versionDichaPorCliente = esOtraVersion ? motorCliente.replace(/^otra\s*:?\s*/i, '').trim() : '';
if (esOtraVersion) motorCliente = '';
const motorUsado = motorFord || motorCliente;

let catalogo = [];
try { catalogo = $('Ford - catalogo concesionario').first().json.response || []; } catch (e) {}

let precios = [];
try { precios = $('Precios fuera de plan').all().map(i => i.json).filter(r => r.modelo); } catch (e) {}

// Año de modelo según el 10º carácter del VIN
const ANIO_VIN = { A: 2010, B: 2011, C: 2012, D: 2013, E: 2014, F: 2015, G: 2016, H: 2017, J: 2018,
  K: 2019, L: 2020, M: 2021, N: 2022, P: 2023, R: 2024, S: 2025, T: 2026, V: 2027, W: 2028 };
const vin = String(fila.chassi || '').trim().toUpperCase();
const anio = vin.length === 17 ? (ANIO_VIN[vin.charAt(9)] || null) : null;

// ---------- 1) Precio según la circular vigente ----------
const hoy = new Date().toISOString().slice(0, 10);
const groupR = Number(fila.model_id) || null;
const km = Number(calc.km_original) || 0;

const coincideModelo = (p) => {
  if (p.group_r && groupR) return Number(p.group_r) === groupR;
  if (!fila.model) return false;
  if (p.group_r) return norm(p.modelo) === norm(fila.model);
  return norm(p.modelo) === norm(fila.model) || sinParentesis(p.modelo) === sinParentesis(fila.model);
};
// -1 = no coincide; 0 = fila sin motor o Ford sin motor; >0 = largo de la coincidencia
// Versión legible de la fila ("Nueva Ranger 2.0L Diésel"): es lo que se le ofrece al cliente
const versionDe = (p) => String(p.servicio || '').split(' - ').slice(1).join(' - ').trim();
const puntajeMotor = (p) => {
  if (!motorFord && motorCliente && versionDe(p) && norm(versionDe(p)) === norm(motorCliente)) return 100;
  const tokens = String(p.motor_ford || '').split('|').map(norm).filter(Boolean);
  if (!tokens.length || !motorUsado) return 0;
  const m = norm(motorUsado);
  const largos = tokens.filter(t => m.includes(t)).map(t => t.length);
  return largos.length ? Math.max(...largos) : -1;
};
const precioDeFila = (p) => {
  if (norm(p.tipo) !== 'programado') return Number(p.precio) || null;
  const lista = String(p.precios_km || '').split('|').map(Number).filter(n => n > 0);
  const intervalo = Number(p.km_intervalo) || 0;
  if (!lista.length || !intervalo || !km) return null;
  const idx = Math.max(1, Math.round(km / intervalo));
  return idx <= lista.length ? { monto: lista[idx - 1], idx } : null;
};

const vigentes = precios.filter(p =>
  coincideModelo(p) &&
  (!anio || (anio >= Number(p.anio_desde) && anio <= Number(p.anio_hasta))) &&
  (!p.vigencia_desde || hoy >= p.vigencia_desde) &&
  (!p.vigencia_hasta || hoy <= p.vigencia_hasta)
).map(p => ({ p, score: puntajeMotor(p) })).filter(c => c.score >= 0);

let precio = null, monto = null, idxKm = null, opcionesMotor = [], versionReferencia = null;
for (const tipo of ['programado', 'iolm', 'motorcraft']) {
  const cands = vigentes.filter(c => norm(c.p.tipo) === tipo)
    .map(c => { const r = precioDeFila(c.p); return { ...c, monto: r && typeof r === 'object' ? r.monto : r, idx: r && typeof r === 'object' ? r.idx : null }; })
    .filter(c => c.monto);
  if (!cands.length) continue;
  const mejor = Math.max(...cands.map(c => c.score));
  const top = cands.filter(c => c.score === mejor);
  if (new Set(top.map(c => c.monto)).size > 1) {
    if (esOtraVersion && !motorFord) {
      // El cliente dijo que no es ninguna de las versiones: se informa como REFERENCIA el precio
      // de la primera versión de la circular (aproximado, lo confirma el asesor)
      precio = top[0].p; monto = top[0].monto; idxKm = top[0].idx;
      versionReferencia = versionDe(top[0].p) || null;
      break;
    }
    // dos precios posibles: no se arriesga. Si Ford no informó el motor, se le pregunta al cliente
    if (!motorFord) opcionesMotor = [...new Set(top.map(c => versionDe(c.p)).filter(Boolean))];
    break;
  }
  // Mismo precio para todas las versiones posibles: no hace falta preguntar el motor.
  // Si son versiones distintas, el ítem no nombra ninguna en particular.
  const versiones = new Set(top.map(c => versionDe(c.p)).filter(Boolean));
  precio = versiones.size > 1
    ? { ...top[0].p, servicio: String(top[0].p.servicio || '').split(' - ')[0] }
    : top[0].p;
  monto = top[0].monto; idxKm = top[0].idx;
  break;
}
const tipoPrecio = precio ? norm(precio.tipo) : null;
// El Servicio Motorcraft es solo cambio de aceite y filtro: se reserva como tal
const esSoloAceite = tipoPrecio === 'motorcraft';

// ---------- 2) Servicio de Ford para reservar ----------
const nRevision = esSoloAceite ? null : (Number(calc.service_number) || null);
// Ids vistos en el catálogo de Ford (se usan solo si el catálogo no responde)
const IDS_CONOCIDOS = { 11: 1413, 12: 1414, 13: 1415, 14: 1416, 15: 1418, 16: 1417, 17: 1419, 18: 1420, 19: 1421, 20: 1422 };
const ID_CAMBIO_ACEITE = 1447;

const buscar = (nombre) => catalogo.find(s => norm(s.serviceName) === norm(nombre));
let servicioFord = null;
if (servicioDeFord && servicioDeFord.serviceId && !esSoloAceite) {
  servicioFord = {
    id: servicioDeFord.serviceId,
    nombre: servicioDeFord.serviceDescription || (nRevision ? `${nRevision}ª Revisión de Mantenimiento` : 'Revisión de Mantenimiento'),
    code: servicioDeFord.service || null,
  };
}
if (!servicioFord && nRevision) {
  const nombre = `${nRevision}ª Revisión de Mantenimiento`;
  const enCatalogo = buscar(nombre);
  if (enCatalogo) servicioFord = { id: enCatalogo.serviceId ?? enCatalogo.id, nombre: enCatalogo.serviceName };
  else if (!catalogo.length && IDS_CONOCIDOS[nRevision]) servicioFord = { id: IDS_CONOCIDOS[nRevision], nombre };
}
if (!servicioFord) {
  const aceite = buscar('Cambio de Aceite y Filtros');
  servicioFord = { id: aceite ? (aceite.serviceId ?? aceite.id) : ID_CAMBIO_ACEITE, nombre: 'Cambio de Aceite y Filtros' };
}
const esAceite = servicioFord.nombre === 'Cambio de Aceite y Filtros';

const includes = precio
  ? [
      { description: `${precio.servicio}: ${precio.incluye}`, quantity: 1, unitPrice: monto, subtotal: monto },
      { description: 'Control de 25 puntos de seguridad', quantity: 1, unitPrice: 0, subtotal: 0 },
      { description: 'Lectura de códigos de falla con scanner FORD', quantity: 1, unitPrice: 0, subtotal: 0 },
    ]
  : [];
const adicionales = precio && precio.adicionales
  ? String(precio.adicionales).split('|').map(s => s.trim()).filter(Boolean)
  : [];

const notaPrecio = tipoPrecio === 'programado'
  ? 'Ford no informó el precio por API: se toma el precio sugerido de la circular de Ford para este service y kilometraje.'
  : 'Kilometraje por encima del plan oficial de Ford: se toma el precio sugerido por Ford para este servicio. Los adicionales se suman solo si corresponden por km o tiempo y se confirman en recepción.';

// ---------- 3) Nota interna para el asesor (va a las observaciones del concesionario en AF) ----------
const $ar = (n) => '$' + Number(n).toLocaleString('es-AR');
const vehiculoTxt = [fila.model, anio].filter(Boolean).join(' ');
const precioAproximado = !!versionReferencia;
let notaInternaAsesor;
if (precioAproximado) {
  notaInternaAsesor = `[Asistente] PRECIO APROXIMADO: el cliente indicó que la versión de su ${vehiculoTxt || 'vehículo'} no es ninguna de las de la circular`
    + (versionDichaPorCliente ? ` (dijo: "${versionDichaPorCliente.slice(0, 80)}")` : '')
    + `. Se le informó como referencia el precio de ${versionReferencia}: ${$ar(monto)}${idxKm ? ` (${idxKm}º service)` : ''}. Confirmar versión y precio con el cliente.`;
} else if (precio) {
  notaInternaAsesor = `[Asistente] Ford no informó precio por API. Se le informó al cliente ${$ar(monto)} según la circular de Ford (${precio.servicio})${versionDichaPorCliente ? `; versión según el cliente: "${versionDichaPorCliente.slice(0, 80)}"` : ''}. Verificar en recepción.`;
} else {
  notaInternaAsesor = `[Asistente] Ford no informó precio y NO se le informó precio al cliente${versionDichaPorCliente ? ` (versión según el cliente: "${versionDichaPorCliente.slice(0, 80)}")` : ''}. Cotizar en recepción.`;
}

return [{
  json: {
    precioAproximado,
    versionReferencia,
    versionDichaPorCliente: versionDichaPorCliente || null,
    notaInternaAsesor,
    // fueraDePlan: true hace que el agente use las reglas de SERVICIO_FUERA_DE_PLAN
    // (no deriva, muestra el precio si precioDisponible, si no lo confirma el asesor)
    fueraDePlan: true,
    motivo,
    precioDisponible: !!precio,
