  const match = horaEspecifica.match(/^(>=|<=|>|<)\s*(\d{1,2}:\d{2})$/);
  if (match) filtroHora = { operador: match[1], minutos: toMinutes(match[2]) };
} catch (e) {}

function cumpleFiltroHora(slot) {
  if (!filtroHora) return true;
  const min = toMinutes(slot);
  if (min === null) return false;
  switch (filtroHora.operador) {
    case '>':  return min >  filtroHora.minutos;
    case '>=': return min >= filtroHora.minutos;
    case '<':  return min <  filtroHora.minutos;
    case '<=': return min <= filtroHora.minutos;
  }
  return true;
}

