  });

  // Si tiene el día completo libre, retorna 0 disponibles
  if (daysOffActivos.some(off => off.allDay)) {
    return {
      json: {
        fechaActual,
        advisorId: a.advisorId,
        advisorName: a.advisorName,
        Slots_Libres: [],
        Cantidad_Slots_Libres: 0
      }
    };
  }

  // 2. Slots bloqueados por franja horaria de daysOffs
  const slotsDaysOff = new Set();
  daysOffActivos.forEach(off => {
    if (off.offStartHour && off.offEndHour) {
      generarSlots(off.offStartHour, off.offEndHour, interval).forEach(s => slotsDaysOff.add(s));
    }
  });

  // 3. Bloqueados sin cita (passerby)
  const reservadosSinCita = new Set((a.nonScheduled || []).map(s => s.passerbyHour).filter(Boolean));

  // 4. Turnos asignados específicamente en esta fecha
  const asignados = new Set(
    (a.dealerSchedule || [])
      .filter(s => s.dateSchedule === fechaActual && s.hourSchedule)
      .map(s => s.hourSchedule)
  );

  // 5. Grilla completa de trabajo del asesor
  const gridCompleto = [
    ...generarSlots(a.amEntrance, a.amExit, interval),
    ...generarSlots(a.pmEntrance, a.pmExit, interval)
  ];

  // 6. Exclusión de ocupados
  const slotsLibres = gridCompleto.filter(h => 
    !reservadosSinCita.has(h) && 
    !asignados.has(h) && 
    !slotsDaysOff.has(h)
  );

  return {
    json: {
      fechaActual,
      advisorId: a.advisorId,
      advisorName: a.advisorName,
      Slots_Libres: slotsLibres,
      Cantidad_Slots_Libres: slotsLibres.length
    }
  };
});

if (resultado.length === 0) {
  return [{
    json: {
      fechaActual,
      vacio: true,
      Slots_Libres: [],
      Cantidad_Slots_Libres: 0
    }
  }];
}

return resultado;

// ==========================================================
// Bloques Ocupados - Fecha Puntual
// ==========================================================

function toMinutes(hhmm) {
  if (!hhmm) return null;
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

function toHHMM(mins) {
  const h = String(Math.floor(mins / 60)).padStart(2, '0');
  const m = String(mins % 60).padStart(2, '0');
  return `${h}:${m}`;
}

function generarSlots(entry, exit, interval) {
  const inicio = toMinutes(entry);
  const fin = toMinutes(exit);
  if (inicio === null || fin === null) return [];

  const slots = [];
  for (let t = inicio; t < fin; t += interval) {
    slots.push(toHHMM(t));
  }
  return slots;
}

// Obtener fecha puntual (desde nodo previo o fallback a la fecha del dealerSchedule)
let fechaActual = null;
try {
  fechaActual = $('Loop Over Items5').item.json.date;
} catch (e) {
  try {
    fechaActual = $('Select rows from a table4').first()?.json?.selected_date;
  } catch (err) {
    fechaActual = "2026-09-08";
  }
}

const inputData = $input.first()?.json?.result?.advisorDealerSchedule;
const interval = inputData?.interval || 20;
const advisors = inputData?.advisors || [];

const resultado = advisors.map(a => {
  const gridCompleto = [
    ...generarSlots(a.amEntrance, a.amExit, interval),
    ...generarSlots(a.pmEntrance, a.pmExit, interval)
  ];

  const slotsBloqueadosSet = new Set();

  // 1. Filtrar daysOffs vigentes para la fecha actual
  const daysOffActivos = (a.daysOffs || []).filter(off => {
    return fechaActual >= off.startDay && fechaActual <= off.endDay;
  });

  const tieneDiaLibreCompleto = daysOffActivos.some(off => off.allDay);
  if (tieneDiaLibreCompleto) {
    gridCompleto.forEach(s => slotsBloqueadosSet.add(s));
  } else {
    // Franjas horarias bloqueadas por descanso
    daysOffActivos.forEach(off => {
      if (off.offStartHour && off.offEndHour) {
        const slotsOff = generarSlots(off.offStartHour, off.offEndHour, interval);
        slotsOff.forEach(s => slotsBloqueadosSet.add(s));
      }
    });
  }

  // 2. Bloqueos por nonScheduled (sin cita / transeúntes)
  (a.nonScheduled || []).forEach(s => {
    if (s.passerbyHour) slotsBloqueadosSet.add(s.passerbyHour);
  });

  // 3. Bloqueos por turnos ya agendados para este día puntual
  (a.dealerSchedule || []).forEach(s => {
    if (s.dateSchedule === fechaActual && s.hourSchedule) {
      slotsBloqueadosSet.add(s.hourSchedule);
    }
  });

  // Ordenar cronológicamente
  const slotsOcupados = Array.from(slotsBloqueadosSet).sort((x, y) => toMinutes(x) - toMinutes(y));

  return {
    json: {
      fechaActual,
      advisorId: a.advisorId,
      advisorName: a.advisorName,
      Slots_Bloqueados: slotsOcupados,
      Cantidad_Slots_Bloqueados: slotsOcupados.length
    }
  };
});

if (resultado.length === 0) {
  return [{
    json: {
      fechaActual,
      vacio: true,
      Slots_Bloqueados: [],
      Cantidad_Slots_Bloqueados: 0
    }
  }];
}

return resultado;

function esFechaPuntual(str) {
  return /^\d{4}-\d{2}-\d{2}$/.test(str.trim());
}

let fechaEspecifica = null;
try {
  const trigger = $('When Executed by Another Workflow').first()?.json || {};
  const fechaCampo = (trigger.fechaEspecifica || '').toString().trim();
  const horaCampo = (trigger.horaEspecifica || '').toString().trim();

  // El campo horaEspecifica a veces trae una fecha en vez de una hora (mapeo cruzado
  // aguas arriba), así que revisamos ambos campos por si viene ahí.
  if (esFechaPuntual(fechaCampo)) {
    fechaEspecifica = fechaCampo;
  } else if (esFechaPuntual(horaCampo)) {
    fechaEspecifica = horaCampo;
  }
} catch (e) {}

if (fechaEspecifica) {
  return [{ json: { date: fechaEspecifica } }];
}

const today = new Date();
const dates = [];

for (let i = 1; i < 21; i++) {
  const date = new Date(today);
  date.setDate(date.getDate() + i);
  dates.push(date.toISOString().split('T')[0]);
}

return dates.map(date => ({ json: { date } }));

