if (precioAproximado) {
  notaInternaAsesor = `[Asistente] PRECIO APROXIMADO: el cliente indicó que la versión de su ${vehiculoTxt || 'vehículo'} no es ninguna de las de la circular`
    + (versionDichaPorCliente ? ` (dijo: "${versionDichaPorCliente.slice(0, 80)}")` : '')
    + `. Se le informó como referencia el precio de ${versionReferencia}: ${$ar(monto)}${idxKm ? ` (${idxKm}º service)` : ''}. Confirmar versión y precio con el cliente.`;
} else if (precio) {
  notaInternaAsesor = `[Asistente] Ford no informó precio por API. Se le informó al cliente ${$ar(monto)} según la circular de Ford (${precio.servicio})${versionDichaPorCliente ? `; versión según el cliente: "${versionDichaPorCliente.slice(0, 80)}"` : ''}. Verificar en recepción.`;
} else {
  notaInternaAsesor = `[Asistente] Ford no informó precio y NO se le informó precio al cliente${versionDichaPorCliente ? ` (versión según el cliente: "${versionDichaPorCliente.slice(0, 80)}")` : ''}. Cotizar en recepción.`;
}

return [{
  json: {
    precioAproximado,
    versionReferencia,
    versionDichaPorCliente: versionDichaPorCliente || null,
    notaInternaAsesor,
    // fueraDePlan: true hace que el agente use las reglas de SERVICIO_FUERA_DE_PLAN
    // (no deriva, muestra el precio si precioDisponible, si no lo confirma el asesor)
    fueraDePlan: true,
    motivo,
    precioDisponible: !!precio,
    // Si es true, el agente le pregunta al cliente cuál de opcionesMotor es su vehículo y vuelve a
    // llamar a get_detail_servicios con motor = la opción elegida (texto exacto)
    requiereMotor: !precio && opcionesMotor.length > 1,
    opcionesMotor: !precio && opcionesMotor.length > 1 ? opcionesMotor : [],
    motorCliente: motorCliente || null,
    precioFuente: precio ? (precio.fuente || 'Circular Ford') : null,
    serviceId: servicioFord.id,
    serviceCode: servicioFord.code || (nRevision && !esAceite ? `SM${String(nRevision).padStart(2, '0')}` : 'ACEITE'),
    serviceDescription: precio && tipoPrecio !== 'programado' ? `${servicioFord.nombre} (${precio.servicio})` : servicioFord.nombre,
    monthService: Number(servicioDeFord && servicioDeFord.monthService) || Number(calc.months) || null,
    km: calc.km_original,
    pricing: precio
      ? { originalPrice: monto, discountPercent: 0, discountAmount: 0, finalPrice: monto }
      : { originalPrice: null, discountPercent: 0, discountAmount: 0, finalPrice: null },
    campaign: null,
    includes,
    adicionalesSegunKmOTiempo: adicionales,
    nota: precio ? notaPrecio : 'Ford no informó el precio de este service: lo confirma el asesor en recepción.',
    motorFord,
    anioModelo: anio,
    intervaloTablaKm: idxKm,
  },
}];

// La nota interna es para el asesor (va a la agenda de Ford), no para el agente.
// totalPrice: mismo campo que devuelve Code26 cuando Ford informa el servicio.
const { notaInternaAsesor, ...respuesta } = $('Servicio fuera de plan').first().json;
respuesta.totalPrice = respuesta.pricing ? respuesta.pricing.finalPrice : null;
return [{ json: respuesta }];
